 String explain429(String details){String d=details.toLowerCase(Locale.ROOT);if(d.contains("per minute")||d.contains("per second")||d.contains("rate")||d.contains("requests per")||d.contains("retry")||d.contains("too many"))return "Gemini limitó la velocidad de peticiones (HTTP 429). Espera un momento; puede reintentarse una vez automáticamente. Detalle: "+details;return "Gemini rechazó la solicitud con HTTP 429. El detalle apunta a cuota/uso agotado o facturación, que no se soluciona reintentando. Revisa AI Studio > Usage y los límites del proyecto. Detalle: "+details;}

 void send(){
  if(requestInProgress)return;String msg=input.getText().toString().trim();if(msg.isEmpty())return;input.setText("");append("TÚ: "+msg);String base=endpoint.getText().toString().trim(),m=model.getText().toString().trim(),k=key.getText().toString().trim();if(!k.isEmpty()){try{saveSecret("gemini_key",k);}catch(Exception e){append("MONDI: No puedo proteger la clave en este dispositivo; revisa Android actualizado.");return;}}else k=readSecret("gemini_key");
  if(k.toLowerCase(Locale.ROOT).contains("curl")||k.toLowerCase(Locale.ROOT).contains("x-goog-api-key")){append("MONDI: Pega solo la clave API, no el comando curl.");return;}if(k.isEmpty()){append("MONDI: Pulsa «Crear clave gratis de Gemini» y guarda aquí tu clave de Google AI Studio.");return;}if(m.isEmpty()){append("MONDI: Falta el modelo Gemini.");return;}if(!base.startsWith("https://generativelanguage.googleapis.com/")){append("MONDI: Usa la URL base https://generativelanguage.googleapis.com/v1beta");return;}
  String url=base.replaceAll("/+$","")+"/models/"+m+":generateContent";final String apiKey=k;requestInProgress=true;cancelRequested=false;sendButton.setText("Detener respuesta");statusView.setText("Gemini está pensando…");
  new Thread(()->{try{JSONObject req=new JSONObject();JSONArray contents=new JSONArray();JSONArray systemParts=new JSONArray();systemParts.put(new JSONObject().put("text","Eres MONDI AI, asistente personal en español. No uses ni digas el nombre del usuario. Para peticiones de comandos, entrega comandos completos listos para copiar, adaptados al sistema indicado, explica dónde ejecutarlos y qué hacen. No inventes que el móvil es un ordenador cuántico: solo simula conceptos; el hardware cuántico requiere servicios externos. Sé claro y seguro; no ayudes a saltarse licencias o protecciones de otras aplicaciones."));req.put("systemInstruction",new JSONObject().put("parts",systemParts));synchronized(conversation){for(int j=Math.max(0,conversation.length()-16);j<conversation.length();j++){JSONObject old=conversation.getJSONObject(j);JSONArray parts=new JSONArray().put(new JSONObject().put("text",old.optString("content","")));contents.put(new JSONObject().put("role","assistant".equals(old.optString("role"))?"model":"user").put("parts",parts));}}contents.put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",msg))));req.put("contents",contents);
   String answer="";for(int attempt=0;attempt<2;attempt++){if(cancelRequested)throw new InterruptedException("cancelled");HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();activeConnection=c;c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("x-goog-api-key",apiKey);try(OutputStream o=c.getOutputStream()){o.write(req.toString().getBytes("UTF-8"));}int status=c.getResponseCode();InputStream stream=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream buf=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1&&buf.size()<1000000)buf.write(chunk,0,n);}String response=buf.toString("UTF-8");if(status==429){String detail=response;try{JSONObject er=new JSONObject(response).optJSONObject("error");if(er!=null)detail=er.optString("message",response);}catch(Exception ignored){}String lower=detail.toLowerCase(Locale.ROOT);boolean rate=lower.contains("per minute")||lower.contains("per second")||lower.contains("rate")||lower.contains("requests per")||lower.contains("too many");String retry=c.getHeaderField("Retry-After");c.disconnect();activeConnection=null;if(attempt==0&&rate&&!cancelRequested){long delay=2;try{delay=Math.min(4,Math.max(1,Long.parseLong(retry)));}catch(Exception ignored){}Thread.sleep(delay*1000);continue;}throw new IOException(explain429(detail));}if(status>=400)throw new IOException("Gemini HTTP "+status+": "+response);JSONArray candidates=new JSONObject(response).getJSONArray("candidates");JSONArray parts=candidates.getJSONObject(0).getJSONObject("content").getJSONArray("parts");StringBuilder a=new StringBuilder();for(int i=0;i<parts.length();i++){String t=parts.getJSONObject(i).optString("text","");if(!t.isEmpty()){if(a.length()>0)a.append("\n");a.append(t);}}answer=a.toString().trim();c.disconnect();activeConnection=null;break;}
   if(cancelRequested)throw new InterruptedException("cancelled");if(answer.isEmpty())throw new IOException("Gemini no devolvió texto. Revisa el modelo y la cuota de AI Studio.");synchronized(conversation){conversation.put(new JSONObject().put("role","user").put("content",msg));conversation.put(new JSONObject().put("role","assistant").put("content",answer));while(conversation.length()>40)conversation.remove(0);}saveConversation();lastAnswer=answer;append("MONDI: "+answer);final String answerToSpeak=answer;if(tts!=null)runOnUiThread(()->{if(ttsReady)tts.speak(answerToSpeak,TextToSpeech.QUEUE_FLUSH,null,"mondi");});
  }catch(InterruptedException e){if(!cancelRequested)append("MONDI: La solicitud se interrumpió.");}catch(Exception e){if(!cancelRequested)append("Error de Gemini: "+e.getMessage());}finally{HttpURLConnection c=activeConnection;if(c!=null)c.disconnect();activeConnection=null;requestInProgress=false;runOnUiThread(()->{sendButton.setEnabled(true);sendButton.setText("Enviar a IA");statusView.setText(cancelRequested?"Respuesta detenida":"Listo");});}}
  ).start();
 }
 void showSearchEngines(){String q=input.getText().toString().trim();if(q.isEmpty()){toast("Escribe lo que quieres buscar primero.");return;}String[] engines={"Google","Bing","DuckDuckGo","Brave","Ecosia","Tor Browser (si está instalado)"};new AlertDialog.Builder(this).setTitle("Buscar con").setItems(engines,(d,i)->{String query=Uri.encode(q);String[] urls={"https://www.google.com/search?q="+query,"https://www.bing.com/search?q="+query,"https://duckduckgo.com/?q="+query,"https://search.brave.com/search?q="+query,"https://www.ecosia.org/search?q="+query,"https://duckduckgo.com/?q="+query};Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse(urls[i]));if(i==5)intent.setPackage("org.torproject.torbrowser");try{startActivity(intent);}catch(ActivityNotFoundException e){toast("Tor Browser no está instalado. Instálalo desde su fuente oficial para usar Tor.");}}).show();}
